package zncimport

import (
	"errors"
	"strings"
	"testing"

	"github.com/4evrd/evrd/internal/store"
)

const zncConf = `// WARNING
//
// Do NOT edit this file while ZNC is running!
Version = 1.8.2
<Listener listener0>
	Port = 6697
	SSL = true
</Listener>
LoadModule = webadmin

<User admin>
	Pass       = sha256#0123abcd#salt#
	Admin      = true
	Nick       = adm
	AltNick    = adm_
	Ident      = admin
	RealName   = Got ZNC?
	ChanBufferSize = 300
	LoadModule = chansaver

	/* a comment
	   over lines */
	<Network libera>
		LoadModule = sasl
		LoadModule = keepnick
		LoadModule = kickrejoin 5
		LoadModule = perform
		LoadModule = autoreply
		LoadModule = simple_away
		Nick = libnick
		Server     = irc.libera.chat +6697
		Server     = irc.eu.libera.chat 6667 serverpass
		TrustedServerFingerprint = AB:CD:EF
		FloodRate = 1.00
		FloodBurst = 4
		IRCConnectEnabled = false

		<Chan #znc>
			Buffer = 50
			AutoClearChanBuffer = false
			Key = sekrit
		</Chan>
		<Chan #idle>
			Detached = true
			Disabled = true
		</Chan>
	</Network>

	<Network oftc>
		Server = irc.oftc.net +6697
	</Network>
</User>

<User bob>
	Pass = md5#x#y#
	Nick = bob
	Server = irc.example.net 6667
	<Chan #old>
	</Chan>
</User>
`

func TestParseConfig(t *testing.T) {
	users, err := ParseConfig([]byte(zncConf))
	if err != nil {
		t.Fatal(err)
	}
	if len(users) != 2 || users[0].Name != "admin" || users[1].Name != "bob" {
		t.Fatalf("users %+v", users)
	}
	nets := users[0].Networks
	if len(nets) != 2 || nets[0].Name != "libera" || nets[1].Name != "oftc" {
		t.Fatalf("admin's networks %+v", nets)
	}
	store.SetSecretKeys(nil)
	var n store.Network
	x := nets[0]
	pb := x.Apply(&n)
	if n.Nick != "libnick" || n.AltNick != "adm_" || n.Username != "admin" || n.Realname != "Got ZNC?" {
		t.Errorf("nicks (the user's are the defaults): %+v", n)
	}
	if s := n.Servers; len(s) != 2 || s[0] != (store.Server{Host: "irc.libera.chat", Port: 6697, TLS: true}) ||
		s[1] != (store.Server{Host: "irc.eu.libera.chat", Port: 6667, Password: "serverpass"}) {
		t.Errorf("servers %+v", s)
	}
	if len(n.Fingerprints) != 1 || n.Fingerprints[0] != "abcdef" || n.FloodRate != 1 || n.FloodBurst != 4 {
		t.Errorf("certs, flood: %+v", n)
	}
	if *x.Enabled {
		t.Error("IRCConnectEnabled = false, imported as enabled")
	}
	if strings.Join(n.Channels, " ") != "#znc #idle" || n.Channel("#znc").Key != "sekrit" ||
		n.Channel("#idle") != (store.ChannelSettings{Detached: true, Disabled: true}) {
		t.Errorf("channels %v %+v", n.Channels, n.ChannelSettings)
	}
	if *pb[""].Lines != 300 || *pb["#znc"].Lines != 50 || *pb["#znc"].AutoClear {
		t.Errorf("playback %+v", pb)
	}
	if n.AuthMethod != "sasl" || !n.Modules["keepnick"].Enabled || n.Modules["kickrejoin"].Settings["delay"] != "5" {
		t.Errorf("modules: %s %+v", n.AuthMethod, n.Modules)
	}
	if _, ok := n.Modules["perform"]; ok {
		t.Error("perform turned on without its commands")
	}
	notes := map[string]string{}
	for _, no := range x.Notes() {
		notes[no.Key] = no.Args[1].(string)
	}
	if notes["irc.znc.loginPassword"] != "sasl" || notes["irc.znc.moduleData"] != "perform" || notes["irc.znc.modulesSkipped"] != "autoreply" {
		t.Errorf("notes %v", x.Notes())
	}

	if p := users[0].Pass; p == nil || *p != (Pass{Method: "sha256", Hash: "0123abcd", Salt: "salt"}) {
		t.Errorf("admin's pass %+v", p)
	}
	if p := users[1].Pass; p == nil || *p != (Pass{Method: "md5", Hash: "x", Salt: "y"}) {
		t.Errorf("bob's pass %+v", p)
	}

	// ZNC before 1.0: the user's servers and channels are its one network
	bob := users[1].Networks
	if len(bob) != 1 || bob[0].Name != "default" || bob[0].Nick != "bob" || bob[0].Servers[0].Host != "irc.example.net" || bob[0].Channels[0].Name != "#old" {
		t.Errorf("bob %+v", bob)
	}
}

func TestUserPass(t *testing.T) {
	for conf, want := range map[string]*Pass{
		"<User a>\n<Pass password>\nMethod = SHA256\nHash = ab\nSalt = s\n</Pass>\n</User>":       {"sha256", "ab", "s"},
		"<User a>\n<Pass password>\nMethod = Argon2id\nHash = $argon2id$v=19$x\n</Pass>\n</User>": {"argon2id", "$argon2id$v=19$x", ""},
		"<User a>\nPass = md5#ab\n</User>":           {"md5", "ab", ""},
		"<User a>\nPass = ab -\n</User>":             {"md5", "ab", ""},
		"<User a>\nPass = plain#p#w\n</User>":        {"plain", "p#w", ""},
		"<User a>\nPass = hunter2\n</User>":          {"plain", "hunter2", ""},
		"<User a>\n<Network n>\n</Network>\n</User>": nil,
	} {
		users, err := ParseConfig([]byte(conf))
		if err != nil {
			t.Fatal(err)
		}
		if got := users[0].Pass; (got == nil) != (want == nil) || (got != nil && *got != *want) {
			t.Errorf("%q: %+v, want %+v", conf, got, want)
		}
	}
}

func TestParseConfigPart(t *testing.T) {
	users, err := ParseConfig([]byte("\t<Network libera>\n\t\tServer = irc.libera.chat +6697\n\t\t<Chan #a>\n\t\t</Chan>\n\t</Network>\n"))
	if err != nil || len(users) != 1 || users[0].Name != "" || len(users[0].Networks) != 1 || users[0].Networks[0].Name != "libera" {
		t.Fatalf("a <Network> on its own: %+v %v", users, err)
	}
	users, err = ParseConfig([]byte("<User solo>\n<Network n>\n</Network>\n</User>\n"))
	if err != nil || len(users) != 1 || users[0].Name != "solo" {
		t.Errorf("a <User> on its own: %+v %v", users, err)
	}
	for _, bad := range []string{"<User a>\n", "</User>\n", "<User a>\nnot a line\n</User>\n"} {
		if _, err := ParseConfig([]byte(bad)); err == nil {
			t.Errorf("%q parsed", bad)
		}
	}
	if _, err := ParseConfig([]byte("Version = 1.8\n")); !errors.Is(err, ErrNotConfig) {
		t.Errorf("no users or networks: %v", err)
	}
	if !LooksLikeConfig([]byte(zncConf)) || LooksLikeConfig([]byte("networks: []")) {
		t.Error("LooksLikeConfig")
	}
}
